        {"unit": "MUNIT10", "title": "At the Clinic", "canDo": "I can talk about clinic day", "dialoguePlace": "Clinic", "readingText": "At clinic, I help. I listen. I write. I speak. My patients ask a question. I answer. My colleagues listen. We work together. We check patients. We give medicine. At clinic, I am happy. I like to help. John also works hard in his health center in Nairobi.", "readingWords": 58, "vocab": ["Learn", "Read", "Write", "Help", "Patient"], "grammar": "I help / I listen", "tryAtHome": "Mime 3 clinic actions"},
        {"unit": "MUNIT11", "title": "My Healthy Friends", "canDo": "I can describe healthy friends", "dialoguePlace": "Clinic", "readingText": "This is my friend Sara. She is kind. She likes to help patients. This is my friend John. He is funny. He likes to work hard for health. We work together. We share our books. We help each other. Healthy friends are good. I love my healthy friends. As adults in East Africa, friends help us be healthy.", "readingWords": 56, "vocab": ["Kind", "Funny", "Share", "Help", "Together"], "grammar": "She is kind. / He is funny.", "tryAtHome": "Describe 1 healthy friend"},
        {"unit": "MUNIT12", "title": "My Clinic Rooms", "canDo": "I can name clinic rooms", "dialoguePlace": "Clinic", "readingText": "This is my clinic in Arusha. It is small and clean. This is the waiting room. Patients wait here. This is the examination room. Doctor checks here. This is the pharmacy. We give medicine here. I like my clinic. My clinic is clean. John works in a clinic in Nairobi.", "readingWords": 56, "vocab": ["Clinic", "Waiting room", "Pharmacy", "Doctor", "Clean"], "grammar": "This is the clinic.", "tryAtHome": "Name rooms in your clinic / house"},
        {"unit": "MUNIT13", "title": "Weather and Health", "canDo": "I can talk about weather and health", "dialoguePlace": "Outside", "readingText": "Today it is sunny. The sun is hot. I wear a hat. Yesterday it was rainy. It rained a lot. We stayed inside. Mosquitoes come in rainy season. We use mosquito nets. Tomorrow it will be cloudy. I like sunny days. I can walk to clinic. What is the weather today? John checks weather for health in Nairobi.", "readingWords": 60, "vocab": ["Sunny", "Rainy", "Cloudy", "Mosquito", "Health"], "grammar": "It is sunny. / It was rainy.", "tryAtHome": "Look outside and say weather + health"},
        {"unit": "MUNIT14", "title": "My Nurse Clothes", "canDo": "I can name medical clothes", "dialoguePlace": "Bedroom", "readingText": "I wear a white coat. I wear trousers. I wear shoes. I wear gloves for patients. When it is cold, I wear a sweater. When it rains, I wear a raincoat. My work clothes are white and blue. I like my clothes. My clothes are clean. In clinic, clean clothes are important. John wears a white coat in Nairobi.", "readingWords": 58, "vocab": ["White coat", "Gloves", "Shoes", "Sweater", "Clean"], "grammar": "I wear a white coat.", "tryAtHome": "Name what you wear for clinic"},
        {"unit": "MUNIT15", "title": "Market and Healthy Food", "canDo": "I can buy healthy food", "dialoguePlace": "Arusha Market", "readingText": "Mary and I go to the market in Arusha. We buy tomatoes. We buy onions. We buy beans. We buy vegetables. How much is this? The seller says: 2000 shillings. Mary pays. We say thank you. The market is busy. Many people are there. Healthy food in market keeps us strong. Markets in Nairobi, Kampala and Dar es Salaam are also busy. John buys healthy food too.", "readingWords": 62, "vocab": ["Market", "Buy", "Vegetables", "Pay", "Healthy"], "grammar": "How much is this?", "tryAtHome": "Role play buying healthy food"},
        {"unit": "MUNIT16", "title": "My Medical Evening", "canDo": "I can talk about evening health", "dialoguePlace": "Home", "readingText": "In the evening, I go home. I wash my hands. I eat healthy dinner with my family. I read medical books. I prepare my lessons. I read a book. I say good night to Mama and Papa. Good night! I sleep. I dream of healthy East Africa. John prepares his clinic notes in Nairobi in the evening.", "readingWords": 56, "vocab": ["Evening", "Dinner", "Wash hands", "Good night", "Sleep"], "grammar": "I wash my hands.", "tryAtHome": "Tell evening health routine"}
