        {"unit": "MUNIT97", "title": "My Medical Legacy", "canDo": "I can talk about medical legacy", "dialoguePlace": "Home", "readingText": "Medical legacy is what remains after you. Not money. Not houses. But what you taught, what you healed, who you helped in health. My grandmother left health stories. My mother left kindness in health. What will I leave? I want to leave a Medical English school for East African health workers. That is my medical legacy.", "readingWords": 60, "vocab": ["Legacy", "Remains", "Taught", "Healed", "Health"], "grammar": "What will I leave?", "tryAtHome": "Write your medical legacy sentence"},
        {"unit": "MUNIT98", "title": "Writing a Medical Book", "canDo": "I can plan a medical book", "dialoguePlace": "Writer Room", "readingText": "Mary wants to write a medical book: Medical English for East African Adults. Chapter 1: Hello, My Health. Chapter 2: My Body. Chapter 3: My Medical Region. She will write one page per day. In 100 days, she will have 100 pages. Writing a medical book needs discipline, not talent. Start with one page. John will help with health chapter.", "readingWords": 64, "vocab": ["Chapter", "Discipline", "Talent", "Page", "Health"], "grammar": "She will write...", "tryAtHome": "Write 1 page of your medical book"},
        {"unit": "MUNIT99", "title": "Mentoring Medical Youth", "canDo": "I can mentor medical youth", "dialoguePlace": "Youth Center", "readingText": "A medical mentor guides, not controls. John mentors younger health workers in Nairobi. He listens to their fears. He shares his mistakes. He encourages them. He says: I was like you. You can help health. Mentoring multiplies health. One mentor can change 100 lives. Mary mentors young nurses in Arusha.", "readingWords": 60, "vocab": ["Mentor", "Guides", "Encourages", "Multiplies", "Health"], "grammar": "A mentor guides...", "tryAtHome": "Mentor 1 younger health worker"},
        {"unit": "MUNIT100", "title": "Isomero Medical Vision - EAC", "canDo": "I can present medical vision", "dialoguePlace": "Isomero Office - Arusha", "readingText": "Isomero means learning. Our medical vision: Every East African health worker speaks Medical English with confidence. We will build apps, clubs, and clinics for health. We will train nurses. We will use Swahili to teach Medical English. We will keep culture. We will open health doors. Isomero is not just an app. It is a health movement. From Burundi to Somalia, we are one health. Mary and John lead it.", "readingWords": 66, "vocab": ["Vision", "Confidence", "Movement", "Train", "Health"], "grammar": "Our vision: Every health worker...", "tryAtHome": "Present Isomero medical vision"},
        {"unit": "MUNIT101", "title": "Global Medical Speaker", "canDo": "I can speak globally for health", "dialoguePlace": "TED Stage", "readingText": "Hello, world. I am Mary from East Africa. I am 26, a Medical English teacher from Arusha. I come from hills and drums. I learned Medical English in a small classroom with no internet. Today, I speak to you about health. My message is simple: Language is power. Health education is freedom. If a woman from Arusha can speak health, anyone can. Never underestimate a nurse with a book. John is with me today from Nairobi.", "readingWords": 72, "vocab": ["Global", "Underestimate", "Freedom", "Power", "Health"], "grammar": "I come from...", "tryAtHome": "Record 2 min TED health talk"},
        {"unit": "MUNIT102", "title": "Medical Research Project", "canDo": "I can present medical research", "dialoguePlace": "University", "readingText": "My medical research asks: Does Medical English help East African health workers help patients? I interviewed 50 health workers in Arusha, Nairobi and Kampala. 80% said Medical English helped. 60% helped patients better. 90% want more Medical English clubs. Conclusion: Medical English opens health opportunities. Recommendation: Teach Medical English from Pre-A1 with local health stories for adults in East Africa. Data speaks.", "readingWords": 62, "vocab": ["Research", "Interviewed", "Conclusion", "Recommendation", "Health"], "grammar": "My research asks...", "tryAtHome": "Interview 3 health workers"},
        {"unit": "MUNIT103", "title": "Building a Medical School", "canDo": "I can plan a medical school", "dialoguePlace": "Arusha", "readingText": "To build a medical school, we need land, bricks, teachers, and medical books. But most important, we need vision. Mary and John will start with one classroom for health workers in Arusha. They will teach 30 health workers. They will use Isomero Medical curriculum. One classroom can become a medical school. One school can become 8 schools in 8 EAC countries.", "readingWords": 62, "vocab": ["Build", "School", "Vision", "Classroom", "Health"], "grammar": "To build a school...", "tryAtHome": "Plan your medical school"},
        {"unit": "MUNIT104", "title": "Graduation - Medical Leader", "canDo": "I can graduate as Medical Leader", "dialoguePlace": "Graduation Hall - Arusha", "readingText": "Today we graduate! Mary and John stand on stage. They started with Hello, I Am Mary - My Health. Now they speak Medical English with confidence. They can describe symptoms, help patients, present, and lead health in 8 EAC countries. From MUNIT1 to MUNIT104, they grew. You also grew. Congratulations! You are a Medical Leader. You are East African. You are Isomero. Go and heal. Go and teach others. The future of East Africa health is yours.", "readingWords": 72, "vocab": ["Graduation", "Congratulations", "Confidence", "Health", "Leader"], "grammar": "We started / Now we can", "tryAtHome": "Record graduation speech - I am Medical Leader"}
